-- Dadyoom-original fourth-grade expression comprehension + open task.
-- Historical BH 2025/26 plan only: NOT officially verified for 2026/27.
-- The open task needs actual teacher evaluation; completion != verified writing/speaking skill.
WITH qa(sort_order,title,prompt,correct,w1,w2,w3,practice_prompt) AS (VALUES
    (1,'التعبير الشفوي: الحيّة بيّة','كيف تصرفت نور لتتعرف إلى تفاصيل تقليد «الحيّة بيّة»؟','اقترحت الرجوع إلى مصدر ثقافي موثوق وسؤال الأسرة','اختلقت تفاصيل دون مصدر','اكتفت بتكرار الشائعات','رفضت سؤال المعلمة','قدم حديثًا من ثلاث جمل عن عادة تراثية تعرفها، واذكر كيف تتحقق من معلومة واحدة عنها.'),
    (2,'التعبير الشفوي — الأسبوع الثاني','كيف بدأ يوسف عرضه عن هواية جمع القصص؟','عرّف الهواية ثم ذكر سبب حبه لها','بدأ بنصيحة ختامية قبل ذكر الموضوع','اكتفى بذكر أسماء الطلاب','لم يقدم فكرة رئيسية','تحدث عن هوايتك: عرّفها، اذكر سبب حبك لها، ثم قدم مثالًا وخاتمة قصيرة.'),
    (3,'التعبير الشفوي — الأسبوع الثالث','على ماذا اتفقت سلمى وصديقتها بعد الحديث عن الحديقة؟','كتابة اقتراح للمحافظة على نظافة المكان','قطف الزهور كل يوم','ترك المكان دون عناية','عدم الاستماع لآراء الآخرين','كوّن حوارًا من ثلاث جمل بين طالبين يقترحان حماية حديقة المدرسة.'),
    (4,'التعبير الشفوي — الأسبوع الرابع','ما التصرف الذي يدل على أمانة فهد في السيناريو؟','سلّم القلم الذي وجده إلى المعلم','احتفظ بالقلم دون سؤال','أخفى القلم عن صاحبه','اتّهم طالبًا آخر','احك موقفًا قصيرًا عن الأمانة، مع سبب الاختيار ونتيجة التصرف، ثم لخّصه كتابةً.'),
    (5,'التعبير الشفوي — الأسبوع الخامس','أي عنصر ورد في وصف هدى لزيارتها المكتبة؟','الكتاب الذي اختارته وما تعلمته','رحلة بحرية إلى جزيرة','منافسة رياضية في الملعب','قصة لا تتعلق بالزيارة','صف زيارة قصيرة لمكتبة أو مكان تعليمي مستخدمًا: أولًا، ثم، وفي النهاية.'),
    (6,'التعبير الشفوي — الأسبوع السادس','بحسب راشد، متى ينجح العمل الجماعي؟','عندما يشارك الجميع ويتقاسمون الأدوار','عندما يؤدي شخص واحد كل الأعمال','عندما يتجنب الطلاب التعاون','عندما تُترك الأدوات دون ترتيب','تحدث عن عمل جماعي شاركت فيه أو تتخيله، وحدد دور كل مشارك وفائدة التعاون.'),
    (7,'التعبير الشفوي — الأسبوع السابع','كيف يجعل المتحدث وصف الشخصية أكثر إقناعًا؟','يذكر موقفًا ملموسًا يثبت كل صفة','يطلق أحكامًا من دون أمثلة','يصف المظهر فقط','يكرر الصفات نفسها دون دليل','صف شخصًا بصورة محترمة مع صفتين، وقدّم موقفًا يدل على كل صفة.'),
    (8,'التعبير الشفوي — الأسبوع الثامن','ما طريقتا الاستعداد للامتحان اللتان ناقشهما الطالبان؟','المراجعة على فترات قصيرة وحل أسئلة متنوعة','السهر طوال الليل دون راحة','ترك المراجعة حتى وقت الامتحان','تجاهل تصحيح الأخطاء','اقترح خطة مراجعة صغيرة تتضمن وقتًا للمراجعة وحل الأسئلة والراحة.'),
    (9,'التعبير الشفوي — الأسبوع التاسع','ما السلوك الرقمي الآمن الذي ذكرته سارة؟','عدم نشر البيانات الشخصية','مشاركة كلمة المرور مع الجميع','نشر المعلومات دون التحقق','فتح أي رابط مجهول','اعرض ثلاث نصائح لاستخدام التقنية التعليمية بأمان، مع مثال للتحقق من معلومة.'),
    (10,'التعبير الشفوي — الأسبوع الحادي عشر','كيف فرقت فاطمة بين ما تراه في الصورة القديمة وتوقعاتها؟','ذكرت المشاهدات أولًا وفصلت عنها التوقعات','قدمت توقعاتها بوصفها حقائق مؤكدة','اخترعت تاريخًا دقيقًا للصورة','تجاهلت سؤال الأسرة','صف صورة قديمة متخيلة: جملتان لما تراه فعلًا وجملة تبدأ بـ«أتوقع».'),
    (101,'الحوار في النص السردي (1)','ما السؤال الذي طرحه حمد على زميله في الحوار الأصلي؟','هل انتهيت من القصة؟','أين اشتريت القلم؟','متى ستذهب إلى الملعب؟','لماذا نسيت الحقيبة؟','اكتب حوارًا من أربعة أسطر عن استعارة كتاب، واستخدم علامتي الاقتباس وعلامة الاستفهام.'),
    (102,'الحوار في النص السردي (2)','كيف أسهم حوار مريم وصديقتها في تحريك أحداث القصة؟','قدّم اقتراحًا صادقًا لحل مشكلة نسيان الواجب','أوقف القصة دون حل','دفع مريم إلى إخفاء الحقيقة','جعل المشكلة أكبر دون سبب','اكتب حوارًا قصيرًا يبدأ بمشكلة مدرسية ثم يُظهر قرارًا يؤدي إلى حل مناسب.'),
    (103,'إنتاج فقرة وصفية: وصف المكان (1)','أين تقع طاولة القراءة في وصف المكتبة؟','في منتصف الغرفة','على سطح المبنى','داخل الحديقة','تحت السلالم','صف مكانًا تعرفه في أربع جمل محددًا مواضع الأشياء باستخدام أمام وخلف وبجوار.'),
    (104,'إنتاج فقرة وصفية: وصف المكان (2)','أي تفصيل سمعي استخدمه عمر لوصف الحديقة؟','زقزقة الطيور','لون العشب الأخضر','ضوء الشمس','شكل الممر','صف حديقة متخيلة بأربع جمل تتضمن لونًا وصوتًا ورائحةً دون تكرار الصفات.'),
    (105,'إنتاج فقرة وصفية: وصف المكان (3)','أي عمل يحافظ على جمال ساحة المدرسة في الفقرة الأصلية؟','المحافظة على نظافتها','إتلاف المقاعد','ترك المخلفات على الأرض','الكتابة على الجدران','اكتب فقرة مترابطة تصف ساحة المدرسة في أربع جمل مع أداتي ربط مختلفتين.'),
    (106,'إنتاج فقرة وصفية: وصف شخص (1)','ما الدليل على تعاون سالم؟','يساعد زملاءه في تنظيم الكتب','ينصرف قبل انتهاء العمل','يرفض مساعدة الآخرين','يقطع حديث زملائه','اكتب وصفًا لشخصية متعاونة، واذكر فعلًا شاهدته أو تتخيله يدل على تعاونها.'),
    (107,'إنتاج فقرة وصفية: وصف شخص (2)','ما السلوك الذي يبين أن هند منظمة؟','ترتب أدواتها بعد النشاط','تترك الأدوات مبعثرة','ترفض حل المشكلات','لا تستمع إلى التوجيهات','صف شخصًا محبًا للتعلم ومنظمًا وقدم شاهدًا عمليًا على كل صفة.'),
    (108,'إنتاج فقرة وصفية: وصف شخص (3)','أي طريقة تجعل وصف فارس محترمًا ودقيقًا؟','الاستدلال على صفاته بأفعاله دون السخرية من مظهره','إطلاق صفات جارحة على الشكل','نقل اتهامات دون دليل','إهمال سلوك الشخصية','اكتب ثلاث جمل تصف شخصية خيالية وصفًا محترمًا، واستشهد بسلوك واحد لكل صفة.'),
    (109,'البطاقة الإرشادية (1)','أي تعليمية تصلح لبطاقة المحافظة على الكتاب؟','أعد الكتاب إلى مكانه بعد القراءة','امزق صفحة منه للتذكير','اطو صفحاته بقوة','اتركه في المطر','اكتب بطاقة إرشادية بعنوان «أحافظ على كتابي»، تتكون من عنوان وثلاث جمل أمر قصيرة.'),
    (110,'البطاقة الإرشادية (2)','ما الصيغة الأنسب لتعليمة سلامة واضحة؟','التزم تعليمات السلامة وامشِ بهدوء','افعل أي شيء دون انتباه','لا أهمية للقواعد','اركض في الممر وقت الازدحام','أنشئ بطاقة سلامة للصف تتضمن عنوانًا وثلاث تعليمات قصيرة قابلة للتنفيذ.')
), targets AS (
 SELECT l.id,qa.* FROM qa
 JOIN public.lessons l ON l.title=qa.title AND l.sort_order=qa.sort_order
 JOIN public.units u ON u.id=l.unit_id AND u.title='الجزء الثاني — التعبير الشفوي والكتابي' AND u.semester=2
 JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=4 AND g.name_ar='الصف الرابع'
 JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
 JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
 WHERE length(coalesce(l.content,''))>350
   AND l.content ILIKE '%ضاديوم%'
   AND ((qa.sort_order<=10 AND l.content LIKE '%سيناريو حوار وتحدث أصلي%')
      OR (qa.sort_order>=101 AND l.content LIKE '%شرح تطبيقي أصلي%'))
)
INSERT INTO public.lesson_activities
 (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
SELECT t.id,'فهم وتنظيم أفكار التعبير — ضاديوم','multiple_choice','assessment',t.prompt,
 jsonb_build_object('origin','DADYOOM_BH_G4_T2_EXPRESSION_ORIGINAL_V1','sourceStatus','HISTORICAL_2025_2026_NOT_VERIFIED_FOR_2026_2027','bookTextCopied',false,'reviewStatus','required','subtype','source_text_comprehension','options',jsonb_build_array(t.correct,t.w1,t.w2,t.w3)),
 jsonb_build_object('correct',t.correct),1,5,true,true
FROM targets t
WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities a WHERE a.lesson_id=t.id AND a.content->>'origin'='DADYOOM_BH_G4_T2_EXPRESSION_ORIGINAL_V1' AND a.activity_type='multiple_choice');

